                reasoning={"effort": "high"},
                input=[
                    {"role": "system", "content": PERSONA_CONTEXT},
                    {"role": "user", "content": request},
                ],
                text={"format": {"type": "json_object"}},
            )
        except Exception as exc:
            raise AgentExecutionError(
                f"Runtime language-model call failed: {type(exc).__name__}: {exc}"
            ) from exc
        raw = getattr(response, "output_text", "")
        try:
            value = json.loads(raw)
        except (TypeError, json.JSONDecodeError) as exc:
            raise AgentExecutionError(
                "Runtime language-model returned malformed JSON."
            ) from exc
        if not isinstance(value, dict):
            raise AgentExecutionError("Runtime language-model returned a non-object JSON value.")
        return value


def _text(value: Any) -> str:
    return value if isinstance(value, str) else str(value or "")


def _string_list(value: Any) -> list[str]:
    if not isinstance(value, list):
        return []
    return [_text(item) for item in value]


def _yes_no(value: str) -> str:
    normalized = value.strip().lower()
    if normalized not in {"yes", "no"}:
        raise ValueError("Please answer exactly yes or no for this INPUT Command.")
    return normalized


def classify_repository_input(value: str) -> str:
    try:
        parse_github_repository_input(value)
    except (TypeError, ValueError):
        return "unclear"
    return "repository_url" if "://" in value.strip() else "repository_name"


def parse_release_request(value: str) -> dict[str, Any]:
    normalized = value.strip()
    if normalized == "overview":
        return {"analysis_mode": "overview"}
    fields = [part.strip() for part in normalized.split(";")]
    if len(fields) != 4 or fields[0] != "asset_match":
        raise ValueError(
            "ReleaseRequest must be overview or asset_match;operating_system;architecture;package_preference."
        )
    allowed = [
        {"windows", "macos", "linux", "other"},
        {"x64", "arm64", "unknown"},
        {"installer", "portable", "archive", "any"},
    ]
    if any(item not in allowed[index] for index, item in enumerate(fields[1:])):
        raise ValueError(
            "ReleaseRequest contains an invalid operating system, architecture, or package preference."
        )
    return {
        "analysis_mode": "asset_match",
        "operating_system": fields[1],
        "architecture": fields[2],
        "package_preference": fields[3],
    }


def _format_size(size: Any) -> str:
    try:
        number = int(size)
    except (TypeError, ValueError):
        number = 0
    if number < 1024:
        return f"{number} bytes"
    if number < 1024 * 1024:
        return f"{number / 1024:.1f} KiB"
    if number < 1024 * 1024 * 1024:
        return f"{number / (1024 * 1024):.1f} MiB"
    return f"{number / (1024 * 1024 * 1024):.2f} GiB"


def select_release_asset(
    release: dict[str, Any], request: dict[str, Any]
) -> dict[str, Any]:
    """Select a maintainer-uploaded asset using explicit platform constraints."""
    assets = [asset for asset in release.get("assets", []) if isinstance(asset, dict)]
    os_tokens = {
        "windows": ("windows", "win32", "win64", "win-", "win_"),
        "macos": ("macos", "mac-os", "osx", "darwin", "\.dmg"),
        "linux": ("linux", "ubuntu", "debian", "appimage", "\.deb", "\.rpm"),
        "other": (),
    }
    arch_tokens = {
        "x64": ("x86_64", "x86-64", "amd64", "x64", "64bit", "64-bit"),
        "arm64": ("arm64", "aarch64"),
        "unknown": (),
    }
    pref_tokens = {
        "installer": (".exe", ".msi", ".dmg", ".pkg", ".deb", ".rpm"),
        "portable": ("portable", "appimage"),
        "archive": (".zip", ".tar.gz", ".tgz", ".tar.xz", ".7z"),
        "any": (),
    }
    operating_system = request.get("operating_system")
    architecture = request.get("architecture")
    preference = request.get("package_preference")
    scored: list[tuple[int, str, dict[str, Any]]] = []
    for asset in assets:
        name = _text(asset.get("name")).lower()
        if any(marker in name for marker in ("source code", "source-code", "src archive")):
            continue
        score = 0
        if operating_system != "other":
            tokens = os_tokens[str(operating_system)]
            if tokens and not any(token in name for token in tokens):
                continue
            if tokens:
                score += 4
        if architecture != "unknown":
            tokens = arch_tokens[str(architecture)]
            if tokens and not any(token in name for token in tokens):
                continue
            if tokens:
                score += 4
        if preference != "any":
            tokens = pref_tokens[str(preference)]
            if tokens and not any(token in name for token in tokens):
                continue
            if tokens:
                score += 2
        scored.append((score, name, asset))
    if not scored:
        return {
            "found": False,
            "reason": (
                "No maintainer-uploaded Release Asset matched the requested "
                f"platform ({operating_system}), architecture ({architecture}), "
                f"and package preference ({preference})."
            ),
        }
    scored.sort(key=lambda item: (-item[0], item[1]))
    return {"found": True, "asset": scored[0][2], "reason": "Selected by explicit compatibility constraints."}


